insert into tests (id, definition) values ('romantic', '{"id":"romantic","slug":"romantik-iliski-testi","name":"İlişki Yapısı Anlık Görünümü","subtitle":"6 boyut · 32 soru · ~7 dakika","inviteCta":"Partnerini davet et","dimensions":{"decision":{"id":"decision","name":"Karar Paylaşımı","short":"Kararlar nasıl ve kimin lehine alınıyor?","index":"power","interpretation":{"yüksek":"Önemli kararları çoğunlukla birlikte alıyorsunuz; sürekli aynı kişi son sözü söylemiyor.","orta":"Kararların çoğunu birlikte alıyorsunuz ama bazı konularda bir taraf daha çok belirleyici oluyor.","düşük":"Kararlar büyük ölçüde tek bir kişide toplanmış görünüyor."}},"domestic":{"id":"domestic","name":"Ev İçi Emek","short":"Fiziksel ev işlerinin dağılımı.","index":"labour","interpretation":{"yüksek":"Ev işlerini aşağı yukarı dengeli paylaşıyorsunuz.","orta":"Ev işlerinde ölçülü bir dengesizlik var; bazı işler hep aynı kişiye kalıyor olabilir.","düşük":"Ev işlerinin çoğunu tek bir kişi yapıyor gibi görünüyor."}},"mental":{"id":"mental","name":"Zihinsel Yük","short":"Planlama ve hatırlama emeğinin dağılımı.","index":"labour","interpretation":{"yüksek":"Neyin ne zaman yapılması gerektiğini hatırlama, planlama gibi görünmeyen işler de dengeli dağılmış.","orta":"Planlama ve hatırlama işlerinde kısmi bir dengesizlik var; bu işler biraz daha çok bir kişiye kalıyor.","düşük":"Planlama ve hatırlama işi büyük ölçüde tek bir kişinin üstünde. Ev işleri eşit görünse bile, kafada taşınan yük eşit olmayabilir."}},"digital":{"id":"digital","name":"Dijital Emek","short":"Araştırma, rezervasyon, koordinasyon emeği.","index":"labour","interpretation":{"yüksek":"Araştırma yapma, rezervasyon ayarlama gibi işleri dengeli paylaşıyorsunuz.","orta":"Bu tür işlerde kısmi bir dengesizlik görünüyor.","düşük":"Araştırma, rezervasyon, mesajlaşma gibi işlerin çoğunu tek bir kişi yapıyor."}},"social":{"id":"social","name":"Sosyal Özerklik","short":"Bireysel sosyal alanın korunması.","index":"autonomy","interpretation":{"yüksek":"Kendi arkadaşlıklarınıza ve zamanınıza saygı duyuluyor; ilişki bireyselliğinizi kısıtlamıyor.","orta":"Kişisel alanınız çoğunlukla korunuyor, ama bazen daralabiliyor.","düşük":"Kişisel alanınızın belirgin şekilde daraldığı görülüyor."}},"family":{"id":"family","name":"Aile Sınırları","short":"Ailelerin ilişki üzerindeki etkisi ve sınırlar.","index":"autonomy","interpretation":{"yüksek":"Ailelerinizle ilişkinizde dengeli ve sağlıklı sınırlar var.","orta":"Aile sınırları çoğunlukla dengeli, ama bazı konularda bir taraf ailesi daha etkili olabiliyor.","düşük":"Bir tarafın ailesi ilişki üzerinde oldukça baskın ya da dengesiz bir etkiye sahip görünüyor."}}},"indices":{"power":{"id":"power","name":"Güç","desc":"Karar ve etki dengesi."},"labour":{"id":"labour","name":"Emek","desc":"Ev işi, zihinsel ve dijital emeğin dağılımı."},"autonomy":{"id":"autonomy","name":"Özerklik","desc":"Bireysel sosyal alan ve aile sınırları."}},"questions":[{"id":0,"dim":"decision","type":"likert","text":"Önemli kararlarımızda her iki tarafın görüşü yaklaşık eşit ağırlıktadır.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":1,"dim":"decision","type":"likert_reverse","text":"Bir konuda anlaşamadığımızda genellikle aynı kişi son sözü söyler.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":2,"dim":"decision","type":"likert_reverse","text":"Partnerimin ihtiyaçları benimkilerden daha sık öncelik kazanır.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":3,"dim":"decision","type":"balance","text":"Tatil, taşınma gibi büyük kararları çoğunlukla kim verir?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":4,"dim":"decision","type":"balance","text":"Büyük harcamalarla ilgili son kararı genellikle kim verir?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":5,"dim":"domestic","type":"balance","text":"Yemek hazırlama işini genellikle kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":6,"dim":"domestic","type":"balance","text":"Ev temizliğini çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":7,"dim":"domestic","type":"balance","text":"Çamaşır ve ütü işlerini çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":8,"dim":"domestic","type":"balance","text":"Günlük market alışverişini genellikle kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":9,"dim":"domestic","type":"likert","text":"Ev işlerinin ara