5,"dim":"mental","type":"likert","text":"Zihinsel yükün (planlama, hatırlama, koordinasyon) aramızdaki dağılımından memnunum.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}],"satisfactionQuestion":true},{"id":16,"dim":"digital","type":"balance","text":"Restoran, tatil veya etkinlik araştırmalarını çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":17,"dim":"digital","type":"balance","text":"Online alışveriş ve rezervasyonları çoğunlukla kim yönetir?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":18,"dim":"digital","type":"balance","text":"Ortak sosyal hayatımızla ilgili mesajlaşmaları çoğunlukla kim yürütür?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":19,"dim":"digital","type":"balance","text":"Fotoğrafları saklama ve paylaşma işini çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":20,"dim":"digital","type":"balance","text":"Ortak takvim ve planları dijital olarak çoğunlukla kim takip eder?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":21,"dim":"digital","type":"likert","text":"Dijital koordinasyon emeğinin (araştırma, rezervasyon, mesajlaşma) dağılımından memnunum.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}],"satisfactionQuestion":true},{"id":22,"dim":"social","type":"likert","text":"Partnerim olmadan arkadaşlarımla vakit geçirmekte kendimi özgür hissederim.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":23,"dim":"social","type":"likert_reverse","text":"İlişkim başladıktan sonra yakın arkadaşlarımla görüşme sıklığım belirgin biçimde azaldı.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":24,"dim":"social","type":"likert","text":"Ayrı hobilerimizin olması ilişkimizde sorun yaratmaz.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":25,"dim":"social","type":"likert_reverse","text":"Partnerimden bağımsız bir plan yaptığımda suçluluk hissederim.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":26,"dim":"social","type":"likert","text":"Partnerim sosyal ilişkilerimi kontrol etmeye çalışmaz.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":27,"dim":"family","type":"likert_reverse","text":"Önemli kararlarımızda ailelerimizin görüşü belirleyici olur.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":28,"dim":"family","type":"likert","text":"Hangi aileyi ne sıklıkta ziyaret edeceğimiz konusunda dengeli bir düzenimiz var.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":29,"dim":"family","type":"balance","text":"Ailelerin ilişkimiz üzerindeki etkisi kimin tarafında daha ağır basar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":30,"dim":"family","type":"likert_reverse","text":"Aile ziyaretlerinde taraflardan biri diğerinden belirgin şekilde baskın.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":31,"dim":"family","type":"likert","text":"Ailelerimizle ilişkimizde sağlıklı sınırlar koyabiliyoruz.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]}]}'::jsonb) on conflict (id) do nothing;
insert into tests (id, definition) values ('friendship', '{"id":"friendship","slug":"arkadaslik-iliskisi-testi","name":"Arkadaşlık Yapısı Anlık Görünümü","subtitle":"6 boyut · 31 soru · ~7 dakika","inviteCta":"Arkadaşını davet et","dimensions":{"initiative":{"id":"initiative","name":"İletişim Girişimi","short":"Görüşme ve iletişimi kim başlatıyor?","index":"reciprocity","interpretation":{"yüksek":"Mesaj atmayı ya da aramayı ikiniz de aşağı yukarı eşit başlatıyorsunuz. Sürekli aynı kişi ilk adımı atmak zorunda kalmıyor.","orta":"Bazen bir tarafın diğerinden biraz daha çok ilk adımı attığı oluyor, ama bu çok belirgin değil.","düşük":"Neredeyse hep aynı kişi mesaj atıyor ya da arıyor. O kişi aramasa, uzun süre haber alamayabilirsiniz."}},"effort":{"id":"effort","name":"Emek Dengesi","short":"Zaman ve çaba yatırımının dağılımı.","index":"reciprocity","interpretation":{"yüksek":"Bu arkadaşlığa ikiniz de aşağı yukarı aynı kadar zaman ve emek harcıyorsunuz.","orta":"Bazen bir taraf diğerinden biraz daha fazla emek harcıyor olabilir, ama fark küçük.","düşük":"Bu arkadaşlık için emeğin çoğunu tek bir kişi harcıyor gibi görünüyor."}},"emotional":{"id":"emotional","name":"Duygusal Destek","short":"Zor zamanlarda dinlenme ve anlaşılma.","index":"support","interpretation":{"yüksek":"Zor zamanlarda birbirinize destek oluyorsunuz, bu karşılıklı işliyor.","orta":"Çoğunlukla birbirinize destek oluyorsunuz ama bazen destek sadece tek taraftan geliyor.","düşük":"Duygusal destek çoğunlukla tek taraftan diğerine akıyor. Bu, destek veren kişiyi yorabilir, destek alamayan kişiyi de yalnız hissettirebilir."}},"practical":{"id":"practical","name":"Pratik Destek","short":"Yardım isteme/verme ve kaynak paylaşımı.","index":"support","interpretation":{"yüksek":"Yardım isteme ve yardım etme ikiniz arasında dengeli işliyor.","orta":"Bazen yardım hep aynı yönde gidiyor — biri hep isteyen, diğeri hep veren taraf oluyor.","düşük":"Pratik yardım (eşya, bilgi, zaman) neredeyse hep aynı kişiden diğerine gidiyor."}},"honesty":{"id":"honesty","name":"Dürüstlük ve Çatışma","short":"Açık iletişim, kırgınlık ve özür dengesi.","index":"trust","interpretation":{"yüksek":"Kırgınlıkları ve anlaşmazlıkları rahatça konuşabiliyorsunuz; birbirinize güveniyorsunuz.","orta":"Bazı konuları konuşmak yerine üstünü örtüp geçiyor olabilirsiniz.","düşük":"Kırgınlıklar genelde konuşulmuyor, ya da özür dileyen hep aynı kişi oluyor. Bu, zamanla birikip büyüyebilecek bir gerginliğe işaret eder."}},"autonomy":{"id":"autonomy","name":"Özerklik","short":"Bağımsız hayata ve diğer ilişkilere saygı.","index":"trust","interpretation":{"yüksek":"Birbirinizin başka arkadaşlıklarına ve kendi hayatına saygı duyuyorsunuz; bu arkadaşlık kişisel alanınızı kısıtlamıyor.","orta":"Genelde birbirinizin alanına saygı duyuyorsunuz ama bazen kıskançlık ya da tedirginlik oluyor.","düşük":"Diğer kişinin kendi kararlarına ya da başka arkadaşlıklarına karşı belirgin bir kıskançlık/sahiplenme var. Bu, kişisel alanın daraldığını gösterir."}}},"indices":{"reciprocity":{"id":"reciprocity","name":"Karşılıklılık","desc":"Girişim ve emek dengesi."},"support":{"id":"support","name":"Destek","desc":"Duygusal ve pratik destek alışverişi."},"trust":{"id":"trust","name":"Güven ve Sınırlar","desc":"Dürüstlük, çatışma yönetimi ve özerklik."}},"questions":[{"id":0,"dim":"initiative","type":"balance","text":"Buluşma/görüşme teklifini genellikle kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla arkadaşım","score":50},{"label":"Neredeyse her zaman arkadaşım","score":0}]},{"id":1,"dim":"initiative","type":"balance","text":"Mesajlaşmayı genellikle kim başlatır?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla arkadaşım","score":50},{"label":"Neredeyse her zaman arkadaşım","score":0}]},{"id":2,"dim":"initiative","t