insert into tests (id, definition) values ('family', '{"id":"family","slug":"aile-iliskisi-testi","name":"Ebeveyn-Çocuk İlişkisi Yapısı Anlık Görünümü","subtitle":"6 boyut · 31 soru · ~7 dakika","inviteCta":"Ebeveynini ya da çocuğunu davet et","visible":false,"contextQuestions":[{"id":"role","text":"Bu testi kim dolduruyor?","options":[{"label":"Ebeveyn","value":"parent"},{"label":"Çocuk (yetişkin çocuk dahil)","value":"child"}]},{"id":"childAge","text":"Çocuk (sen ya da testteki çocuk) 18 yaşından küçük mü?","options":[{"label":"Evet, 18 yaşından küçük","value":"under18"},{"label":"Hayır, 18 yaşında ya da daha büyük","value":"over18"}]}],"disclaimerNote":"Ebeveyn-çocuk ilişkisinde bazı asimetriler (ör. yaşa bağlı karar payı farkı) yapısal olarak meşrudur; her asimetri sorun anlamına gelmez.","dimensions":{"decision":{"id":"decision","name":"Karar Payı","short":"Hayatını ilgilendiren kararlarda sözün geçiyor mu?","index":"power","interpretation":{"yüksek":"Kararları çoğunlukla birlikte alıyorsunuz; söz hakkı dengeli görünüyor.","orta":"Kararların çoğunu birlikte alıyorsunuz ama bazı konularda söz hakkı tek kişide toplanabiliyor.","düşük":"Kararlar büyük ölçüde tek kişide toplanmış görünüyor."},"conditionalNotes":[{"contextQuestionId":"childAge","whenValue":"under18","band":"düşük","note":"Not: çocuk 18 yaşından küçükse kararlarda az söz hakkı olması yaşına göre normal olabilir; tek başına sorun anlamına gelmez."}]},"listening":{"id":"listening","name":"Sözün Dinlenmesi","short":"Konuşurken sözün kesilmeden, öğüt yağmuruna tutulmadan dinleniyor musun?","index":"power","interpretation":{"yüksek":"Birbirinizi sözünü kesmeden dinliyorsunuz; konuşma karşılıklı işliyor.","orta":"Genelde birbirinizi dinliyorsunuz ama bazen söz kesiliyor ya da istenmeyen öğüt geliyor.","düşük":"Genelde bir taraf hep konuşuyor, diğeri hep dinliyor."},"conditionalNotes":[{"contextQuestionId":"childAge","whenValue":"under18","band":"düşük","note":"Not: çocuk 18 yaşından küçükse ebeveynin çok konuşup yönlendirmesi yaşına göre normal olabilir; tek başına sorun anlamına gelmez."}]},"emotionalLabour":{"id":"emotionalLabour","name":"Duygusal Emek","short":"Zor anda moral desteği kimden kime akıyor?","index":"labour","interpretation":{"yüksek":"Zor zamanlarda birbirinize destek oluyorsunuz; teselli etme işi tek kişiye kalmıyor.","orta":"Çoğunlukla birbirinize destek oluyorsunuz ama bazen bir taraf daha çok veren konumda kalıyor.","düşük":"Duygusal desteğin çoğu tek bir kişiden geliyor gibi görünüyor."},"conditionalNotes":[{"contextQuestionId":"childAge","whenValue":"under18","band":"düşük","note":"Not: çocuk 18 yaşından küçükse duygusal desteğin çoğunlukla ebeveynden çocuğa gitmesi yaşına göre normaldir; tek başına sorun anlamına gelmez. Ama tam tersi oluyorsa (çocuk ebeveynini teselli ediyorsa) bu ayrıca konuşulmalı."}]},"practicalSupport":{"id":"practicalSupport","name":"Pratik Destek","short":"Zaman, para, iş gücü gibi somut yardım nasıl dağılıyor?","index":"labour","interpretation":{"yüksek":"Zaman, para, iş gücü gibi somut yardım iki yönlü akıyor; yük tek kişiye kalmıyor.","orta":"Çoğunlukla karşılıklı yardımlaşıyorsunuz ama bazen yük bir tarafa kayabiliyor.","düşük":"Pratik yükün çoğu tek bir kişide toplanmış görünüyor."},"conditionalNotes":[{"contextQuestionId":"childAge","whenValue":"under18","band":"düşük","note":"Not: çocuk 18 yaşından küçükse maddi ve pratik desteğin çoğunlukla ebeveynden çocuğa gitmesi yaşına göre normaldir; tek başına sorun anlamına gelmez."}]},"trust":{"id":"trust","name":"Güven ve Kontrol","short":"İlişki güvenle mi, kontrolle mi yürüyor?","index":"autonomy","interpretation":{"yüksek":"Güven ön planda; sürekli kontrol etme ya da denetleme ihtiyacı yok.","orta":"Genelde güven var ama bazı konularda kontrol etme isteği öne çıkabiliyor.","düşük":"Güvenmek yerine sürekli kontrol etme/denetleme öne çıkıyor görünüyor."}},"privacy":{"id":"privacy","name":"Özel Alan","short":"Kişisel sınırlar ve mahremiyet korunuyor mu?","index":"autono