insert into tests (id, definition) values ('roommate', '{"id":"roommate","slug":"ev-arkadasligi-testi","name":"Ev Arkadaşlığı Yapısı Anlık Görünümü","subtitle":"6 boyut · 31 soru · ~7 dakika","inviteCta":"Ev arkadaşını davet et","dimensions":{"chores":{"id":"chores","name":"Ev İşi Dağılımı","short":"Temizlik, çöp, bulaşık gibi günlük işler nasıl paylaşılıyor?","index":"labour","interpretation":{"yüksek":"Ev işlerini dengeli paylaşıyorsunuz; günlük yük tek kişiye kalmıyor.","orta":"Ev işi dağılımında ölçülü bir dengesizlik var; bazı işler bir kişide daha çok toplanabiliyor.","düşük":"Günlük ev işlerinin çoğu tek bir kişide toplanmış görünüyor."}},"expenses":{"id":"expenses","name":"Ortak Masraf Dengesi","short":"Kira, fatura, market gibi ortak giderler adil paylaşılıyor mu?","index":"labour","interpretation":{"yüksek":"Ortak masrafları adil ve düzenli şekilde paylaşıyorsunuz.","orta":"Masraf paylaşımında kısmi bir dengesizlik var; takip etmek/hatırlatmak bazen tek kişiye kalabiliyor.","düşük":"Ortak masrafları takip etme ve ödeme işinin çoğu tek bir kişide toplanmış görünüyor."}},"standards":{"id":"standards","name":"Düzen ve Temizlik Uyumu","short":"Temizlik ve düzen beklentileri birbirine ne kadar yakın?","index":"harmony","interpretation":{"yüksek":"Temizlik ve düzen beklentileriniz büyük ölçüde örtüşüyor; ortak bir orta yol bulabiliyorsunuz.","orta":"Beklentilerde kısmi bir uyumsuzluk var; bazı konularda biriniz diğerine uyum sağlamak zorunda kalıyor.","düşük":"Temizlik/düzen beklentileriniz belirgin şekilde uyuşmuyor; uyum sağlama işi tek kişiye kalmış görünüyor."}},"communication":{"id":"communication","name":"İletişim ve Çatışma Çözümü","short":"Ev ile ilgili sorunlar ve anlaşmazlıklar nasıl konuşuluyor?","index":"harmony","interpretation":{"yüksek":"Ev ile ilgili sorunları doğrudan ve açıkça konuşabiliyorsunuz; gerginlikler birikmiyor.","orta":"Genelde açık konuşuyorsunuz ama bazı rahatsızlıklar dile getirilmeden içte kalabiliyor.","düşük":"Rahatsızlıklar gen